'use strict';
const KEY='guanlan-prototype-v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const now=()=>new Date().toISOString();
const id=()=>crypto.randomUUID();
const stamp=s=>new Date(s).toLocaleString('zh-CN',{hour12:false});
const initial=()=>({schema:1,active:'ai',tab:'framework',records:[
{id:'ai',title:'AI 的发展，如何传导到存储需求？',kind:'事件与产业',subtitle:'把播客中的产业启发，拆成可验证的研究路径。',demo:true,version:1,status:'待验证',claim:'如果 AI 应用带来持续的数据读写需求，部分存储环节可能受益；但需求增长能否转化为公司利润，还需要订单、供给与价格证据。',conditions:'需同时验证：需求确实新增、供应商能够承接、供给扩张没有抵消价格与利润。',questions:['需求增加发生在训练、推理，还是一般数据存储？','哪个环节存在瓶颈，新增供给多久可以出现？','订单变化能否转化为收入、毛利率和现金流？'],path:['AI 应用增加','数据读写需求','存储环节','公司经营结果'],sources:[{id:'ai-s1',title:'AI 与存储需求 · 教学材料',kind:'原创教学示例',version:1,created:now(),text:'这是一份虚构的教学材料，不对应真实播客、公司或市场预测。\n\n如果 AI 应用持续增加，数据读写和存储需求可能随之增加。但训练、推理与一般存储的需求结构并不相同。\n\n行业需求扩大并不保证每家供应商的利润增长。供给扩张、产品差异、客户议价和价格变化，都会影响经营结果。\n\n要检验受益假设，需要分别寻找需求、订单、产能、价格、毛利率与现金流的证据。当前材料没有提供公司名单或相关数值。'}],references:[{source:'ai-s1',segment:2},{source:'ai-s1',segment:3}],signals:[{name:'需求是否新增',question:'区分训练、推理与一般存储；查找可比口径的数据。',state:'缺少证据',ref:2},{name:'供需能否支持价格',question:'核对扩产节奏、产品替代和客户议价变化。',state:'缺少证据',ref:3},{name:'收入能否变成现金',question:'连接订单、毛利率、回款与资本开支。',state:'缺少证据',ref:4}],history:[]},
{id:'method',title:'把“优势”变成能检查的问题',kind:'方法与框架',subtitle:'从抽象方法到自己的研究纪律，先识别能验证的部分。',demo:true,version:1,status:'待验证',claim:'将“优势”作为待验证的能力假设：明确自己理解哪类业务、信息来自哪里、什么证据会推翻判断，再积累复盘记录。',conditions:'本卡用于组织学习与复盘；不从单篇材料推导胜率、赔率或个人仓位。',questions:['哪些业务驱动因素，我能独立解释并找到证据？','我的判断与市场共识有什么不同，依据是什么？','什么结果说明原来的判断错了？何时复盘？'],path:[],sources:[{id:'method-s1',title:'如何检查自己的研究优势 · 教学材料',kind:'原创教学示例',version:1,created:now(),text:'这是一份原创教学材料，用于演示方法卡的整理流程，并非书籍原文。\n\n理解一个投资方法，与拥有可以重复验证的优势，是两件不同的事。可以先记录自己理解的业务、判断依据和可能推翻判断的证据。\n\n没有长期记录时，不应把主观熟悉程度直接转换为精确胜率或仓位比例。应先通过研究日志和后续复盘检验能力边界。'}],references:[{source:'method-s1',segment:2},{source:'method-s1',segment:3}],signals:[{name:'能否解释业务',question:'记录业务驱动因素及可追溯依据。',state:'缺少证据',ref:2},{name:'能否复盘判断',question:'保留当时判断、反证条件和后续结果。',state:'缺少证据',ref:3}],history:[]}
]});
let state,storageError=false;
try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):initial();if(state.schema!==1||!Array.isArray(state.records)||!state.records.length)throw Error('格式不兼容');}catch(e){state=initial();storageError=true;}
let currentTab=state.tab||'framework';
const current=()=>state.records.find(r=>r.id===state.active)||state.records[0];
const segments=s=>s.text.split(/\n\s*\n/).filter(x=>x.trim());
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageError=false;$('#save-state').textContent='已保存在本浏览器';return true;}catch(e){storageError=true;$('#save-state').textContent='保存失败 · 请先导出备份';toast('浏览器存储不可用，本次改动尚未持久保存');return false;}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3200);}
function openDialog(title,body,buttons=''){const d=$('#dialog');$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="close" aria-label="关闭">×</button></div>${body}${buttons?`<div class="actions">${buttons}</div>`:''}`;d.querySelector('.close').onclick=()=>d.close();if(!d.open)d.showModal();}
function refButton(source,segment,label){return `<button class="source-link" data-source="${esc(source)}" data-segment="${segment}">${esc(label||`原文 §${segment}`)} ↗</button>`;}
function render(){const r=current();$('#record-count').textContent=state.records.length;$('#records').innerHTML=state.records.map(x=>`<button class="record ${x.id===r.id?'active':''}" data-record="${esc(x.id)}"><strong><span class="dot">${x.kind==='方法与框架'?'◇':'◈'}</span>${esc(x.title)}</strong><small>${esc(x.kind)} · v${x.version}${x.demo?' · 示例':''}</small></button>`).join('');$('#crumb').textContent=r.kind;$('#title').textContent=r.title;$('#subtitle').textContent=r.subtitle;$('#meta').innerHTML=`<span class="pill">${esc(r.kind)}</span><span class="pill">${r.sources.length} 份材料</span><span class="pill warm">${esc(r.status)}</span><span class="pill">记录 v${r.version}</span>`;$('#notice').textContent=r.demo?'教学示例：以下内容为预置流程演示，未调用 AI，也不对应真实公司或市场预测。':'手动整理模式：资料仅存本浏览器。尚未连接 AI，研究假设与更新建议由你填写。';$('#history-count').textContent=r.history.length;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===currentTab)));$('#panel').innerHTML=currentTab==='framework'?framework(r):currentTab==='evidence'?evidence(r):leads(r);bindPanel();$('#save-state').textContent=storageError?'存储读取或保存异常 · 请导出备份':'已保存在本浏览器';}
function sourcesCard(r){return `<section class="card"><h3>这份研究从哪里来</h3>${r.sources.map(s=>`<div class="mini-source"><div><strong>${esc(s.title)}</strong><small>${esc(s.kind)} · 来源 v${s.version} · ${segments(s).length} 段</small></div>${refButton(s.id,0,'查看')}</div>`).join('')}<button class="text-button" id="add-source">＋ 补充新材料</button></section>`;}
function updateCard(r){return `<section class="card update-box"><div class="overline">让研究随着证据变化</div><h3>${r.pending?'有一条待确认的更新':'新信息，改变了什么？'}</h3><p>${r.pending?'先对比新旧判断。确认后才会写入研究记录。':'添加材料，记录它支持、削弱或补充了哪一个判断。'}</p><button class="button" id="update">${r.pending?'对比并确认更新 →':'准备一条更新 →'}</button></section>`;}
function framework(r){return `<div class="grid"><div><section class="card hypothesis-card"><div class="card-head"><span class="overline">${r.kind==='方法与框架'?'我的方法卡':'当前研究假设'} · v${r.version}</span><button class="button small" id="edit-claim">编辑</button></div><p class="hypothesis">${esc(r.claim||'还没有研究假设。先阅读原文，再写下你想验证的一句话。')}</p><div>${r.references.map(x=>refButton(x.source,x.segment)).join(' ')}</div><div class="divider"></div><h3>成立的条件与使用边界</h3><p class="muted version-text">${esc(r.conditions)}</p><button class="text-button" id="confirm">${r.status==='已确认，待验证'?'已确认整理内容 ✓':'确认这份整理 →'}</button></section><section class="card"><div class="card-head"><h3>下一步，先回答这些问题</h3><span class="pill">${r.questions.length} 个待办</span></div>${r.questions.map((q,i)=>`<div class="row"><span class="number">0${i+1}</span><div><strong>${esc(q)}</strong><p>找到依据后，在「指标与证据」中记录。</p></div></div>`).join('')}</section></div><aside>${updateCard(r)}${sourcesCard(r)}</aside></div>`;}
function evidence(r){return `<div class="grid"><div><section class="card"><div class="card-head"><h2>把判断拆成证据</h2><span class="pill">不补齐不存在的数据</span></div><p class="muted">原文提出了问题，不代表已经证明了结论。逐项补充支持、反对或不足以判断的依据。</p><div class="signal header"><span>观察什么</span><span>怎样验证</span><span>当前状态</span></div>${r.signals.map((s,i)=>`<div class="signal"><strong>${esc(s.name)}</strong><div>${esc(s.question)}<small>${s.note?esc(s.note):'尚未记录外部验证结果'}</small>${s.source?refButton(s.source,s.segment):s.ref?refButton(r.sources[0].id,s.ref):''}</div><div><span class="pill warm">${esc(s.state)}</span><button class="text-button" data-signal="${i}">记录证据 ↗</button></div></div>`).join('')}${!r.signals.length?'<div class="empty"><strong>还没有验证问题</strong><p>添加你想观察的指标或证据。</p></div>':''}<button class="text-button" id="new-signal">＋ 添加验证问题</button></section><div class="callout">“缺少证据”不等于“已被否定”；“原文提到”也不等于“已验证”。证据状态由你判断。</div></div><aside>${sourcesCard(r)}</aside></div>`;}
function leads(r){return `<div class="grid"><div><section class="card"><div class="overline">从主题出发 · 不必先有标的</div><h2>${r.kind==='方法与框架'?'先建立研究纪律':'可能的影响路径'}</h2>${r.path.length?`<div class="path">${r.path.map((p,i)=>`${i?'<i>→</i>':''}<span>${esc(p)}</span>`).join('')}</div><p class="muted">每一条箭头都需要证据；方向成立，也不代表受益幅度与公司利润已被证明。</p>`:'<p class="muted">这份材料提供研究方法，目前不足以导出行业或公司名单。</p>'}</section><section class="card"><div class="card-head"><h3>候选研究对象</h3><span class="pill">${(r.candidates||[]).length} 个</span></div>${(r.candidates||[]).map(c=>`<div class="row"><span class="number">◇</span><div><strong>${esc(c.name)}</strong><p>${esc(c.reason)}</p><small class="muted">用户提出 · 尚未验证</small></div></div>`).join('')||'<div class="empty"><strong>暂时没有公司，也是一种有效结果</strong><p>先明确受影响的环节和待验证条件。<br>材料没有提供的公司，不会被自动补进来。</p></div>'}<button class="text-button" id="candidate">＋ 记录我想进一步研究的对象</button></section></div><aside><section class="card"><h3>沿着路径继续提问</h3>${r.questions.map(q=>`<div class="question">${esc(q)}</div>`).join('')}</section>${updateCard(r)}</aside></div>`;}
function bindPanel(){document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{state.active=b.dataset.record;render();persist();});document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>showSource(b.dataset.source,Number(b.dataset.segment)));const bind=(sel,fn)=>{if($(sel))$(sel).onclick=fn;};bind('#edit-claim',()=>editClaim());bind('#add-source',()=>importSource(true));bind('#update',()=>current().pending?reviewUpdate():prepareUpdate());bind('#confirm',()=>{const r=current();if(!r.claim)return toast('请先填写研究假设');if(r.status==='已确认，待验证')return toast('已确认整理内容，判断仍需验证');r.status='已确认，待验证';event(r,'确认整理','确认整理内容，不表示研究假设已经成立。');render();persist();});bind('#new-signal',()=>editSignal(-1));document.querySelectorAll('[data-signal]').forEach(b=>b.onclick=()=>editSignal(Number(b.dataset.signal)));bind('#candidate',candidate);}
function event(r,type,note,before,after){r.history.unshift({time:now(),type,note,before,after,version:r.version});}
function showSource(sourceId,n){const s=current().sources.find(x=>x.id===sourceId);if(!s)return toast('来源不存在');openDialog(s.title,`<p class="muted">${esc(s.kind)} · 来源 v${s.version} · 导入于 ${esc(stamp(s.created))}<br>段落号是本次导入文本的定位编号，不是书籍页码或播客时间戳。</p>${segments(s).map((p,i)=>`<div class="segment ${i+1===n?'selected':''}" id="seg-${i+1}"><b>§${i+1} · 来源 v${s.version}</b>${esc(p)}</div>`).join('')}`);if(n)setTimeout(()=>$('#seg-'+n)?.scrollIntoView({block:'center'}),50);}
function editClaim(){const r=current();openDialog('编辑研究整理',`<label for="claim">研究假设 / 方法</label><textarea id="claim" maxlength="3000">${esc(r.claim)}</textarea><label for="conditions">成立条件与使用边界</label><textarea id="conditions" maxlength="3000">${esc(r.conditions)}</textarea><p class="muted">保存后保留旧版本，状态回到待验证。现有原文引用保留，请检查它是否仍支持新的表述。</p>`,`<button class="primary" id="save-claim">保存为新版本</button>`);$('#save-claim').onclick=()=>{const claim=$('#claim').value.trim(),conditions=$('#conditions').value.trim();if(!claim)return toast('请填写研究假设');if(claim===r.claim&&conditions===r.conditions){$('#dialog').close();return;}const before=r.claim;const oldConditions=r.conditions;r.claim=claim;r.conditions=conditions;r.version++;r.status='待验证';event(r,'手动修改','条件修改前：'+oldConditions+'\n条件修改后：'+conditions,before,claim);$('#dialog').close();render();persist();};}
function importSource(append=false){openDialog(append?'补充一份新材料':'导入材料，开始研究',`<p class="muted">粘贴文字或导入 UTF-8 TXT / MD，最多 20,000 字、200 KB。当前仅做本地整理，不调用 AI。</p><label for="source-title">材料标题</label><input id="source-title" maxlength="120" placeholder="例如：一期让我想继续研究的播客"><label for="source-kind">来源类型</label><select id="source-kind"><option>原始文章 / 文稿</option><option>转录文本</option><option>AI 整理稿</option><option>个人笔记</option></select><label for="source-file">或选择文件</label><input class="file" type="file" accept=".txt,.md,text/plain,text/markdown" id="source-file"><label for="source-text">材料正文</label><textarea id="source-text" placeholder="粘贴内容；空行会被保留为段落分隔。"></textarea>${append?'':'<label for="research-kind">整理方向</label><select id="research-kind"><option>事件与产业</option><option>方法与框架</option></select>'}<div class="error" id="import-error" role="alert"></div>`,`<button class="primary" id="save-source">${append?'保存新材料':'建立研究记录'}</button>`);$('#source-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>204800||!(/\.(txt|md)$/i).test(f.name)){$('#import-error').textContent='只接受不超过 200 KB 的 TXT / MD 文件。';return;}try{const text=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());$('#source-text').value=text;if(!$('#source-title').value)$('#source-title').value=f.name.replace(/\.(txt|md)$/i,'');$('#import-error').textContent='';}catch{$('#import-error').textContent='无法按 UTF-8 读取，请将文件另存为 UTF-8。';}};$('#save-source').onclick=()=>{const title=$('#source-title').value.trim(),text=$('#source-text').value.trim().replace(/\r\n?/g,'\n');if(!title||!text||text.length>20000||new Blob([text]).size>204800){$('#import-error').textContent='请填写标题和正文；正文不能超过 20,000 字 / 200 KB。';return;}const s={id:id(),title,text,kind:$('#source-kind').value,version:1,created:now()};if(append){const r=current();if(r.sources.some(x=>x.text===text)){ $('#import-error').textContent='这份正文已经导入，请避免重复添加。';return;}r.sources.push(s);event(r,'添加材料',title);}else{const r={id:id(),title,kind:$('#research-kind').value,subtitle:'从原文中留下一个值得验证的问题。',demo:false,version:1,status:'待整理',claim:'',conditions:'先记录适用条件；暂不推导具体股票、胜率或仓位。',questions:['原文最值得验证的判断是什么？','需要哪些证据，它在什么情况下不成立？'],path:[],sources:[s],references:[],signals:[],history:[]};state.records.push(r);state.active=r.id;currentTab='framework';state.tab=currentTab;event(r,'建立记录','手动导入材料；没有调用 AI。');}$('#dialog').close();render();persist();toast(append?'材料已保存，原研究判断保持原样':'材料已保存，可以开始手动整理');};}
function sourceSelect(r,selected,seg){return `<label for="e-source">关联来源</label><select id="e-source"><option value="">暂不关联</option>${r.sources.map(s=>`<option value="${esc(s.id)}" ${selected===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select><label for="e-segment">原文段落号（关联来源时必填）</label><input id="e-segment" type="number" min="1" value="${seg||1}">`;}
function validRef(){const source=$('#e-source').value,n=Number($('#e-segment').value);if(!source)return null;const s=current().sources.find(x=>x.id===source);if(!s||!Number.isInteger(n)||n<1||n>segments(s).length)throw Error('段落号不在该来源范围内，请先查看原文。');return {source,segment:n};}
function editSignal(i){const r=current(),s=r.signals[i]||{name:'',question:'',state:'缺少证据',note:''};openDialog('记录验证问题与证据',`<label for="signal-name">观察什么</label><input id="signal-name" maxlength="120" value="${esc(s.name)}"><label for="signal-question">怎样验证</label><input id="signal-question" maxlength="500" value="${esc(s.question)}"><label for="signal-state">你对证据的判断</label><select id="signal-state">${['缺少证据','支持假设','削弱假设','不足以判断'].map(x=>`<option ${s.state===x?'selected':''}>${x}</option>`).join('')}</select><label for="signal-note">证据内容与判断理由</label><textarea id="signal-note" maxlength="3000">${esc(s.note||'')}</textarea>${sourceSelect(r,s.source,s.segment)}<p class="muted">证据状态是你的判断；来源只做文字定位，不代表平台核实了真实性。</p><div id="signal-error" class="error" role="alert"></div>`,`<button class="primary" id="save-signal">保存证据</button>`);$('#save-signal').onclick=()=>{try{const ref=validRef();const value={name:$('#signal-name').value.trim(),question:$('#signal-question').value.trim(),state:$('#signal-state').value,note:$('#signal-note').value.trim(),...(ref||{})};if(!value.name||!value.question)throw Error('请填写观察项和验证方法。');if(value.state!=='缺少证据'&&(!value.note||!ref))throw Error('判断支持、削弱或不足以判断时，请填写理由并关联原文段落。');if(i<0)r.signals.push(value);else r.signals[i]=value;event(r,'记录证据',value.name+'：'+value.state);$('#dialog').close();render();persist();}catch(e){$('#signal-error').textContent=e.message;}};}
function candidate(){openDialog('记录候选研究对象','<p class="muted">由你主动提出；不会自动认定该对象受益。</p><label for="candidate-name">公司 / 行业 / 环节名称</label><input id="candidate-name" maxlength="120"><label for="candidate-reason">为什么值得研究？还缺什么证据？</label><textarea id="candidate-reason" maxlength="2000"></textarea>', '<button class="primary" id="save-candidate">保存候选对象</button>');$('#save-candidate').onclick=()=>{const name=$('#candidate-name').value.trim(),reason=$('#candidate-reason').value.trim();if(!name||!reason)return toast('请填写名称和研究理由');const r=current();r.candidates||=[];r.candidates.push({name,reason});event(r,'添加候选对象',name+'：'+reason);$('#dialog').close();render();persist();};}
function prepareUpdate(){const r=current();openDialog('准备一条研究更新',`<p class="muted">填写新材料如何改变你的判断。这里只保存待审建议，不直接覆盖当前版本。</p><label for="update-claim">建议修改后的判断</label><textarea id="update-claim" maxlength="3000">${esc(r.claim)}</textarea><label for="update-reason">变化原因 / 新证据</label><textarea id="update-reason" maxlength="2000" placeholder="例如：新材料指出需求增长可能被供给扩张抵消，因此需要增加验证条件。"></textarea>${sourceSelect(r)}${r.demo?'<button class="text-button" id="sample-update">载入一次教学更新示例</button>':''}<div class="error" id="update-error" role="alert"></div>`,`<button class="primary" id="save-update">保存待审更新</button>`);if($('#sample-update'))$('#sample-update').onclick=()=>{const method=r.kind==='方法与框架';$('#update-claim').value=method?'将“优势”视为待验证的能力假设，先建立研究日志与反证条件，再以连续复盘检验自己的能力边界。':'AI 带来的存储需求只是起点；只有需求增长、供给约束与供应商经营数据共同支持，才进一步研究利润受益的可能性。';$('#update-reason').value=method?'教学演示：提高对长期记录和可反驳性的重视；这不是新的外部事实。':'教学演示：重新阅读原文的供给与价格条件，将“需求受益”收紧为需要经营数据共同支持的假设。不是新事实。';$('#e-source').value=r.sources[0].id;$('#e-segment').value=3;};$('#save-update').onclick=()=>{try{const after=$('#update-claim').value.trim(),reason=$('#update-reason').value.trim(),reference=validRef();if(!after||after===r.claim)throw Error('请填写与当前判断不同的更新建议。');if(!reason||!reference)throw Error('请说明变化原因，并关联依据所在的原文段落。');r.pending={after,reason,reference,baseVersion:r.version,before:r.claim,created:now()};event(r,'提出待审更新',reason);$('#dialog').close();render();persist();reviewUpdate();}catch(e){$('#update-error').textContent=e.message;}};}
function reviewUpdate(){const r=current(),p=r.pending;if(!p)return;const stale=p.baseVersion!==r.version;openDialog('确认这条变化，才更新研究',`<p class="muted">${stale?'当前记录已被编辑，这条建议基于旧版本。请取消后重新准备。':`从 v${r.version} 更新到 v${r.version+1} · 尚未生效`}</p><div class="compare"><div><div class="overline">提出建议时 · v${p.baseVersion}</div>${esc(p.before)}</div><div class="after"><div class="overline">待确认的判断</div>${esc(p.after)}</div></div><label>为什么变化</label><p class="muted">${esc(p.reason)}</p>${refButton(p.reference.source,p.reference.segment,'核对依据')}`,`<button class="button" id="reject-update">取消这条建议</button>${stale?'':'<button class="primary" id="accept-update">确认更新</button>'}`);$('#dialog').querySelector('[data-source]').onclick=()=>{showSource(p.reference.source,p.reference.segment);};$('#reject-update').onclick=()=>{event(r,'取消更新',p.reason);delete r.pending;$('#dialog').close();render();persist();};if($('#accept-update'))$('#accept-update').onclick=()=>{if(r.version!==p.baseVersion)return toast('版本已变化，请重新准备更新');r.claim=p.after;r.version++;r.status='已确认，待验证';if(!r.references.some(x=>x.source===p.reference.source&&x.segment===p.reference.segment))r.references.push(p.reference);event(r,'确认更新',p.reason,p.before,p.after);delete r.pending;$('#dialog').close();render();persist();toast('已更新；旧版本保留在修订记录');};}
function history(){const r=current();openDialog('修订记录',`<p class="muted">记录手动整理和确认过程。只有编辑判断或采纳更新会增加研究版本号。</p>${r.history.map(h=>`<div class="event"><strong>${esc(h.type)} · v${h.version}</strong><small>${esc(stamp(h.time))}</small><p>${esc(h.note)}</p>${h.before!==undefined?`<details><summary>查看变更前后</summary><p>修改前：${esc(h.before)}</p><p>修改后：${esc(h.after)}</p></details>`:''}</div>`).join('')||'<div class="empty">还没有修订。你可以从编辑一次假设开始。</div>'}`);}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#import').onclick=()=>importSource();$('#history').onclick=history;
$('#about').onclick=()=>openDialog('这个版本能做什么','<p>这是「观澜」本地交互原型：支持材料导入、段落定位、手动编辑、证据记录、待审更新、修订历史与导出。</p><p>示例内容是原创教学材料；目前没有调用 AI，也没有接入实时行情或完成与 Open Notebook 的集成。</p><p>资料只保存到当前浏览器的 localStorage。清理浏览器数据、切换浏览器或端口后，记录可能不可见。请用导出保留副本。</p><p>更新需要你确认。这里整理研究过程，不生成买卖、收益或仓位建议。</p>');
$('#edit-title').onclick=()=>{const r=current();openDialog('编辑记录标题',`<label for="record-title">标题</label><input id="record-title" maxlength="120" value="${esc(r.title)}">`,'<button class="primary" id="save-title">保存</button>');$('#save-title').onclick=()=>{const title=$('#record-title').value.trim();if(!title)return toast('标题不能为空');event(r,'修改标题',r.title+' → '+title);r.title=title;$('#dialog').close();render();persist();};};
$('#export').onclick=()=>{const r=current();download('观澜-研究记录-'+r.id+'.json',JSON.stringify({schema:1,exportedAt:now(),mode:'local-manual-prototype',record:r},null,2),'application/json;charset=utf-8');toast('已导出当前记录，包含原文与修订历史');};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{currentTab=b.dataset.tab;state.tab=currentTab;render();persist();});
$('.tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key)||!e.target.dataset.tab)return;e.preventDefault();const tabs=[...document.querySelectorAll('[data-tab]')],i=tabs.indexOf(e.target),next=tabs[(i+(e.key==='ArrowRight'?1:2))%3];next.click();next.focus();});
render();if(!storageError)persist();
